import{_ as e,o as a,c as t,Q as r}from"./chunks/framework.b67c47e6.js";const k=JSON.parse('{"title":"Delivery & Racks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/logistics/delivery/index.md","filePath":"guide/logistics/delivery/index.md","lastUpdated":1786994704000}'),i={name:"guide/logistics/delivery/index.md"},o=r('<h1 id="delivery-racks" tabindex="-1">Delivery &amp; Racks <a class="header-anchor" href="#delivery-racks" aria-label="Permalink to &quot;Delivery &amp; Racks&quot;">​</a></h1><p>The Delivery view is where you decide how finished panels will travel: you arrange them on racks, and that arrangement drives the order the factory produces them in.</p><nav class="table-of-contents"><ul><li><a href="#when-to-use-it">When to use it</a></li><li><a href="#two-things-with-two-names">Two things with two names</a></li><li><a href="#rack-setups">Rack setups</a></li><li><a href="#building-a-rack-load">Building a rack load</a><ul><li><a href="#reading-the-capacity-bars">Reading the capacity bars</a></li></ul></li><li><a href="#setting-the-production-order">Setting the production order</a></li><li><a href="#marking-panels-as-loaded">Marking panels as loaded</a></li><li><a href="#printing-rack-labels">Printing rack labels</a></li><li><a href="#the-rack-drawing">The rack drawing</a></li></ul></nav><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Rack planning happens <strong>before</strong> production, not after:</p><ol><li>You arrange the racks the way the panels need to ship and be built on site.</li><li>That arrangement sets the production order.</li><li>The factory produces the panels.</li><li>Workers mark each panel as loaded on its rack as it comes off the line.</li></ol><p>So the panels you are arranging have not been made yet. That is normal, and the view shows their real status without treating &quot;waiting&quot; as a problem.</p><h2 id="two-things-with-two-names" tabindex="-1">Two things with two names <a class="header-anchor" href="#two-things-with-two-names" aria-label="Permalink to &quot;Two things with two names&quot;">​</a></h2><ul><li>A <strong>rack setup</strong> is a kind of rack your factory owns — an A-frame, a wall rack, a flat bed. You own several identical ones of each; the app does not track which physical unit gets used.</li><li>A <strong>rack load</strong> is one rack filled with panels for one project.</li></ul><h2 id="rack-setups" tabindex="-1">Rack setups <a class="header-anchor" href="#rack-setups" aria-label="Permalink to &quot;Rack setups&quot;">​</a></h2><p>Manage them from <strong>Rack setups</strong> in the company section of the menu.</p><table><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>What people call this kind of rack.</td></tr><tr><td><strong>Loading pattern</strong></td><td>A-frame (panels on both sides), single side, or flat bed.</td></tr><tr><td><strong>Usable length</strong></td><td>How long a row can be. Panels placed side by side have to fit in it.</td></tr><tr><td><strong>Stack depth per side</strong></td><td>How much thickness you can stack away from the frame.</td></tr><tr><td><strong>Max panel height</strong></td><td>The tallest panel the rack takes.</td></tr></tbody></table><p>The three sizes are guides, not rules. The app warns when a load goes over them and lets you carry on.</p><p>When a rack goes out of service, <strong>archive</strong> it. It disappears from the dropdowns and every load ever made with it keeps working. Deleting is only possible for a setup no load has ever used.</p><h2 id="building-a-rack-load" tabindex="-1">Building a rack load <a class="header-anchor" href="#building-a-rack-load" aria-label="Permalink to &quot;Building a rack load&quot;">​</a></h2><p>Press <strong>New rack load</strong>, or <em>Edit</em> on an existing one. The editor opens fullscreen.</p><ol><li>Pick the rack setup on the right. The capacity bars appear once it is set.</li><li>Filter the panel list on the left by production line, phase, batch or scheduled date.</li><li>Click a panel to put it on the rack.</li><li>Drag panels to reorder them. Drag two into the same row to place them side by side. Drag onto the strip marked <code>+</code> to start a new row.</li><li>Fill in the description, the location and, if you use it, a status.</li><li>Press <strong>Save load</strong>.</li></ol><p>The row against the frame is marked with a padlock: those panels are strapped to the rack and come off last. You do not set it — it is always the first row you load on each side.</p><h3 id="reading-the-capacity-bars" tabindex="-1">Reading the capacity bars <a class="header-anchor" href="#reading-the-capacity-bars" aria-label="Permalink to &quot;Reading the capacity bars&quot;">​</a></h3><p>Each row has a bar showing how much of the rack length it uses, and each side shows how deep the stack has got. Green is fine, amber is close, red is over. Nothing is blocked: you decide what fits.</p><p>If a panel shows <strong>Dimensions not measured</strong>, its design has not been analysed yet, so the app is drawing it at a placeholder size. Run the analysis to see the real one.</p><h2 id="setting-the-production-order" tabindex="-1">Setting the production order <a class="header-anchor" href="#setting-the-production-order" aria-label="Permalink to &quot;Setting the production order&quot;">​</a></h2><p>This is done where production order already lives: the <strong>panel sorting dialog of a batch</strong>. There you get a <strong>Sort by rack loading</strong> button, which arranges the panels the way their racks get loaded — load by load, and inside each one starting from the row against the frame. Each panel also shows a small chip with its rack and its position on it, so you can check the order against the plan before saving.</p><h2 id="marking-panels-as-loaded" tabindex="-1">Marking panels as loaded <a class="header-anchor" href="#marking-panels-as-loaded" aria-label="Permalink to &quot;Marking panels as loaded&quot;">​</a></h2><p>Once panels come off the line, mark them:</p><ul><li><strong>On the whole load</strong> — <em>Mark all loaded</em> or <em>Mark delivered</em>, straight from the load&#39;s card or from the rack&#39;s own page. The card shows two chips with how many panels are loaded and how many delivered, reading <strong>ALL LOADED</strong> or <strong>ALL DELIVERED</strong> once every panel is there.</li><li><strong>One panel at a time</strong> — the rack button in the <a href="/guide/viewer/">Viewer</a>.</li></ul><p>This is what fills the delivery chart on the dashboard, so it is worth doing.</p><h2 id="printing-rack-labels" tabindex="-1">Printing rack labels <a class="header-anchor" href="#printing-rack-labels" aria-label="Permalink to &quot;Printing rack labels&quot;">​</a></h2><p>Generate <a href="/guide/reports/qr_stickers/">Rack Load Stickers</a> for a load. One rack per A4 sheet, landscape. The QR takes the whole left half of the sheet, so it can be scanned from across the workshop and at an angle. Beside it: the load name, the rack and its loading pattern, the project, the client, the location, the drawing, and the panels in loading order with the strapped rows marked.</p><p>Scanning the QR opens the rack&#39;s own page on a phone or tablet, with the drawing, the panel list and the two marking buttons. Stickers printed before this change still work.</p><h2 id="the-rack-drawing" tabindex="-1">The rack drawing <a class="header-anchor" href="#the-rack-drawing" aria-label="Permalink to &quot;The rack drawing&quot;">​</a></h2><p>The same drawing appears wherever the load does — the card, the rack&#39;s page, the rack button in the viewer, and the printed sticker. One band per row in loading order, panels at their real sizes, the strapped row highlighted, and the frame where it physically sits.</p><p>Each panel is drawn as a cross-section: its width along the rack by its thickness into the stack, with the height written on it. On screen it also shows the panel&#39;s priority within its batch as <code>number/total</code>, and a chip once that panel is loaded or delivered.</p><p>It is drawn from the arrangement itself, so it is never out of date with what you saved.</p>',34),n=[o];function s(h,l,d,c,p,g){return a(),t("div",null,n)}const w=e(i,[["render",s]]);export{k as __pageData,w as default};
